import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { Toaster } from 'react-hot-toast';
import Login from './components/Login';
import Register from './components/Register';
import Dashboard from './components/Dashboard';
import ProblemList from './components/ProblemList';
import ProblemDetail from './components/ProblemDetail';
import Submissions from './components/Submissions';
import CreateProblem from './components/CreateProblem';
import { AuthProvider, useAuth } from './contexts/AuthContext';
import Navbar from './components/Navbar';
import './App.css';

const PrivateRoute = ({ children }) => {
  const { token } = useAuth();
  return token ? children : <Navigate to="/login" />;
};

const AdminRoute = ({ children }) => {
  const { token, user } = useAuth();
  return token && (user?.role === 'admin' || user?.role === 'setter') 
    ? children 
    : <Navigate to="/" />;
};

function App() {
  return (
    <AuthProvider>
      <Router>
        <div className="app">
          <Navbar />
          <Toaster 
            position="top-right"
            toastOptions={{
              duration: 4000,
              style: {
                background: '#333',
                color: '#fff',
                borderRadius: '10px',
                padding: '16px',
              },
              success: {
                icon: '✅',
                style: {
                  background: '#1a1a2e',
                  border: '1px solid #4CAF50',
                },
              },
              error: {
                icon: '❌',
                style: {
                  background: '#1a1a2e',
                  border: '1px solid #f44336',
                },
              },
            }}
          />
          <Routes>
            <Route path="/login" element={<Login />} />
            <Route path="/register" element={<Register />} />
            <Route path="/" element={<PrivateRoute><Dashboard /></PrivateRoute>} />
            <Route path="/problems" element={<PrivateRoute><ProblemList /></PrivateRoute>} />
            <Route path="/problems/:id" element={<PrivateRoute><ProblemDetail /></PrivateRoute>} />
            <Route path="/submissions" element={<PrivateRoute><Submissions /></PrivateRoute>} />
            <Route path="/create-problem" element={<AdminRoute><CreateProblem /></AdminRoute>} />
          </Routes>
        </div>
      </Router>
    </AuthProvider>
  );
}

export default App;
